코드:
int a = 5;
int b = a++ + ++a;
System.out.println(a + " " + b);

int a = 0;
if (a != 0 && 10 / a > 1) {
    System.out.println("A");
} else {
    System.out.println("B");
}

int score = 85;
if (score >= 90) {
    System.out.println("A");
} else if (score >= 80) {
    System.out.println("B");
} else {
    System.out.println("C");
}

int n = 2;
switch (n) {
    case 1: System.out.print("one ");
    case 2: System.out.print("two ");
    case 3: System.out.print("three ");
        break;
    default: System.out.print("other");
}

int x = 5;
if (x > 3)
    if (x > 10)
        System.out.println("A");
else
    System.out.println("B");

String s = "b";
switch (s) {
    case "a": System.out.println(1); break;
    case "b": System.out.println(2); break;
    default:  System.out.println(3);
}

int x = 0;
if (x == 0)
    x++;
    x++;
System.out.println(x);

int n = 0;
String r = n > 0 ? "양수" : n < 0 ? "음수" : "영";
System.out.println(r);

int sum = 0;
for (int i = 1; i <= 10; i++) {
    sum += i;
}
System.out.println(sum);

int sum = 0;
for (int i = 1; i <= 10; i++) {
    if (i % 3 == 0) continue;
    sum += i;
}
System.out.println(sum);

for (int i = 0; ; i++) {
    if (i == 4) break;
    System.out.print(i);
}

int count = 0;
for (int i = 0; i < 3; i++) {
    for (int j = 0; j < i; j++) {
        count++;
    }
}
System.out.println(count);

outer:
for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
        if (j == 1) continue outer;
        System.out.print(i + "" + j + " ");
    }
}

int[] arr = {1, 2, 3};
for (int x : arr) {
    x *= 2;
}
System.out.println(arr[0]);

int[] a = {1, 2, 3};
int[] b = a;
b[0] = 9;
System.out.println(a[0]);

int[] a = {4, 9, 2};
int max = a[0];
for (int x : a) {
    if (x > max) max = x;
}
System.out.println(max);

int[] a = new int[5];
for (int i = 0; i < a.length; i++) {
    a[i] = i * i;
}
System.out.println(a[4]);

String a = "hi";
String b = new String("hi");
System.out.println((a == b) + " " + a.equals(b));

static int add(int a, int b) {
    return a + b;
}

System.out.println(add(2, 3));

static void print(int x)    { System.out.print("int "); }
static void print(double x) { System.out.print("double"); }

print(5);
print(5.0);

static int fact(int n) {
    return n <= 1 ? 1 : n * fact(n - 1);
}

System.out.println(fact(5));

static void change(int x) {
    x = 100;
}

int a = 1;
change(a);
System.out.println(a);

static int sq(int x) {
    return x * x;
}

System.out.println(sq(sq(2)));

static int sum(int... nums) {
    int s = 0;
    for (int n : nums) s += n;
    return s;
}

System.out.println(sum() + " " + sum(1, 2, 3));

static class Dog {
    String name;
    Dog(String n) { name = n; }
}

Dog d = new Dog("Bori");
System.out.println(d.name);

static class Counter {
    int c;
    void inc() { c++; }
}

Counter a = new Counter();
a.inc();
a.inc();
System.out.println(a.c);

static class P {
    static int cnt = 0;
    P() { cnt++; }
}

new P();
new P();
new P();
System.out.println(P.cnt);

static class Box {
    int w;
    Box(int w) { this.w = w; }
}

System.out.println(new Box(5).w);

static class A {
    int x = 1;
}

A a = new A();
A b = a;
b.x = 5;
System.out.println(a.x);

static class A {
    int v;
    A(int v) { this.v = v; }
}

A a1 = new A(1);
A a2 = new A(1);
System.out.println(a1 == a2);

static void f(int[] a) {
    a[0] = 5;
}

int[] arr = {1};
f(arr);
System.out.println(arr[0]);

static void f(String s) {
    s = "B";
}

String s = "A";
f(s);
System.out.println(s);

static void f(int[] a) {
    a = new int[]{9};
}

int[] arr = {1};
f(arr);
System.out.println(arr[0]);

static int f(int x) {
    return x + 1;
}

int a = 1;
a = f(a);
System.out.println(a);

static void swap(int a, int b) {
    int t = a; a = b; b = t;
}

int x = 1, y = 2;
swap(x, y);
System.out.println(x + " " + y);
